document.addEventListener('input',e=>{const el=e.target;if(el.dataset.search){search[el.dataset.search]=el.value;$(el.dataset.search==='games'?'#game-grid':'#account-list').innerHTML=el.dataset.search==='games'?gameCards():accountRows()}if(el.dataset.input==='global-cpu'){send({type:'global',key:'cpu',value:el.value},false);$('#global-cpu-output').textContent=el.value+'%';if($('#account-list'))$('#account-list').innerHTML=accountRows();if($('.session-list'))$('.session-list').innerHTML=sessionRows()}if(el.dataset.input==='batch-target')toolBatchTarget=el.value;if(el.dataset.input==='tool-volume'){const acc=state.accounts.find(x=>String(x.id)===toolAudioAccount);if(acc)acc.volume=Number(el.value);else toolGlobalVolume=Number(el.value);$('#tool-volume-value').textContent=el.value}if(el.dataset.volume){const a=state.accounts.find(a=>a.id===Number(el.dataset.volume));a.volume=Number(el.value);$('#volume-'+a.id).textContent=a.volume+'%'}if(el.dataset.input==='custom-destination'){state.destination=el.value;const select=$('[data-input=destination]');let custom=$('option[value=custom]',select);if(!custom){custom=document.createElement('option');custom.value='custom';select.append(custom)}custom.textContent=tr('Custom destination','Destino personalizado');select.value='custom'}if(el.dataset.input==='skin'){draft.skin=el.value;$('.avatar-stage').outerHTML=avatarModel()}});
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.input;if(el.dataset.setting){settingsFlags[el.dataset.setting]=el.checked;return}if(k==='demo-font'){settingsFlags.font=el.value;document.querySelector('.app-shell').style.fontFamily=el.value}if(k==='demo-port')apiPort=el.value;if(el.dataset.toolsAccount){const n=Number(el.dataset.toolsAccount);toolsSelected=el.checked?[...new Set([...toolsSelected,n])]:toolsSelected.filter(x=>x!==n);renderMain();return}if(el.dataset.select)send({type:'select',id:el.dataset.select});if(el.dataset.queueCheck){const id=Number(el.dataset.queueCheck);pendingQueue=el.checked?[...new Set([...pendingQueue,id])]:pendingQueue.filter(x=>x!==id)}if(el.dataset.individual){send({type:'individual',id:el.dataset.id,key:el.dataset.individual,value:el.value==='global'?null:el.value});}if(el.dataset.version)state.accounts.find(a=>a.id===Number(el.dataset.version)).version=el.value||null;if(k?.startsWith('global-')&&k!=='global-cpu')send({type:'global',key:k.slice(7),value:el.value});if(k==='destination'&&el.value!=='custom'){state.destination=el.value;const custom=$('[data-input=custom-destination]');if(custom)custom.value=''}if(k==='apply-on-launch')state.applyOnLaunch=el.checked;if(k==='batch-action')toolBatchAction=el.value;if(k==='tool-audio-account'){toolAudioAccount=el.value;toolAudioInherit=true;renderMain()}if(k==='tool-inherit'){toolAudioInherit=el.checked;renderMain()}if(k==='tool-audio-enabled')toolAudioEnabled=el.checked;if(k==='tool-version-account'){state.account=Number(el.value);renderMain()}if(k==='avatar-category'){category=el.value;renderMain()}if(k==='metadata-account'){metadataAccount=Number(el.value);renderMain()}if(k==='active-account'){state.account=Number(el.value);draft={...account().look};renderMain()}if(k==='language'){language=el.value;localize()}if(k==='motion'){state.motion=el.checked;applyTheme()}if(k==='scale'){state.scale=Number(el.value);render()}if(k==='background-mute')state.backgroundMute=el.checked});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='schedule-form'){e.preventDefault();const f=new FormData(form);demoSchedules.push({name:String(f.get('name')),action:String(f.get('action'))});renderMain();notify(tr('Sample schedule saved; it will not run.','Agendamento fictício salvo; ele não será executado.'));return}if(form.id==='preset-form'){e.preventDefault();const f=new FormData(form),id=Number(form.dataset.id),accounts=[...(presetDraft??state.presets.find(p=>p.id===id)?.queue??[])];if(id)send({type:'preset-update',id,name:f.get('presetName'),destination:f.get('destination'),delay:f.get('delay'),cpu:f.get('cpu'),accounts});else{state.presets.push({id:Math.max(0,...state.presets.map(p=>p.id))+1,name:String(f.get('presetName')).trim(),destination:String(f.get('destination')),queue:accounts,delay:Number(f.get('delay')),cpu:Number(f.get('cpu'))});selectedPreset=state.presets.at(-1).id;render()}presetDraft=null;presetFormDraft=null;notify(tr('Sample preset saved.','Perfil fictício salvo.'));return}if(form.id==='group-form'){e.preventDefault();const f=new FormData(form);const groupId=Number(form.dataset.id);send({type:'group-save',groupId,name:f.get('groupName'),accounts:groupDraft});selectedGroup=groupId||state.accountGroups.at(-1)?.id;groupFormDraft=null;renderMain();notify(tr('Sample group saved.','Grupo fictício salvo.'));return}if(form.id==='metadata-form'){e.preventDefault();const f=new FormData(form);send({type:'metadata-save',id:metadataAccount,tags:f.get('tags'),notes:f.get('notes'),fields:f.get('fields')});notify(tr('Sample notes saved.','Notas fictícias salvas.'));return}if(e.target.id!=='demo-form')return;e.preventDefault();const f=e.target,v=new FormData(f).get('name').trim();if(!v)return;const k=f.dataset.kind,id=Number(f.dataset.id);if(k==='account')send({type:'account-add',value:v});if(k==='account-rename')send({type:'account-rename',id,value:v});if(k==='alias')send({type:'friend-alias',id,value:v});if(k==='preset')send({type:'preset-save',value:v});if(k==='outfit'){state.outfits.push({...draft,id:Math.max(...state.outfits.map(o=>o.id))+1,name:v});state.tab='outfits';render()}$('#modal').close()});
let dragged=null;document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag]');if(row&&!queueRunning){dragged=Number(row.dataset.drag);e.dataTransfer.setData('text/plain',String(dragged));e.dataTransfer.effectAllowed='move'}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag]')&&!queueRunning)e.preventDefault()});document.addEventListener('drop',e=>{const row=e.target.closest('[data-drag]');if(row&&dragged&&!queueRunning){e.preventDefault();send({type:'queue-place',id:dragged,target:row.dataset.drag});dragged=null}});
let pointer=null;document.addEventListener('pointerdown',e=>{const stage=e.target.closest('.avatar-stage');if(stage){pointer={id:e.pointerId,x:e.clientX,start:angle,stage};stage.setPointerCapture(e.pointerId)}});document.addEventListener('pointermove',e=>{if(pointer&&pointer.id===e.pointerId){angle=pointer.start+(e.clientX-pointer.x)*.65;$('.avatar-model',pointer.stage).style.setProperty('--turn',angle+'deg')}});document.addEventListener('pointerup',()=>pointer=null);document.addEventListener('pointercancel',()=>pointer=null);
document.addEventListener('keydown',e=>{if(e.target.closest('.avatar-stage')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();angle+=e.key==='ArrowLeft'?-15:15;$('.avatar-model').style.setProperty('--turn',angle+'deg')}if(e.key==='Escape'&&$('#app-shell').classList.contains('expanded'))toggleExpand(false)});
function toggleExpand(force){const open=force??!$('#app-shell').classList.contains('expanded');$('#app-shell').classList.toggle('expanded',open);document.body.style.overflow=open?'hidden':'';if(open){$('#app-titlebar-exit')?.remove();$('#app-top-actions').insertAdjacentHTML('beforeend',`<button class="app-btn" id="app-titlebar-exit">${tr('Exit fullscreen','Sair da tela cheia')} ×</button>`);$('#app-titlebar-exit').onclick=()=>toggleExpand(false)}else $('#app-titlebar-exit')?.remove()}
$('#language').onclick=()=>{language=language==='en'?'pt':'en';localize()};$('#reset-demo').onclick=()=>{queueCancel=true;queueEpoch++;queueRunning=false;clearInterval(macroTimer);const{theme,motion}=state;state=freshState();state.theme=theme;state.motion=motion;search={accounts:'',games:''};draft={...account().look};gameFilter='all';render();notify(tr('Demo reset. Your theme is kept.','Demonstração reiniciada. Seu tema foi mantido.'))};$('#expand-demo').onclick=()=>toggleExpand();$('#open-image').onclick=()=>{$('#expanded-image').src=$('#gallery-image').src;$('#expanded-image').alt=$('#gallery-image').alt;$('#expanded-caption').textContent=$('#gallery-caption').textContent;$('#image-modal').showModal()};$('#close-image').onclick=()=>$('#image-modal').close();for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d)d.close()});
